// CONFIG: the shared settings of ALL flows. Edit here only.
// In: any message from an inject (on deploy, or the Apply button).
// Out: nothing. The settings go to global context: glob.get('cfg').
var cfg = {
  // Root folder in the data lake. Every flow writes below it:
  // reference/, pbi_report/source/, report/, candidate/, logs/.
  root: 'eu_report',
  // Platform: 'legacy' = old Insights Hub (gateway.eu1.mindsphere.io),
  // 'xcelerator' = new platform (api.eu1.siemens.app). No default: set one.
  platform: 'SET_legacy_OR_xcelerator',
  // Technical user. Fill in after import. Do not share the flow filled in.
  // tenantName is used by legacy only, xcTenantId (10 digits) by xcelerator.
  tenantName: 'reckitt',
  xcTenantId: 'PUT_TENANT_ID_HERE',
  clientId: 'PUT_CLIENT_ID_HERE',
  clientSecret: 'PUT_CLIENT_SECRET_HERE',
  // One entry per site of the report.
  // reportSource: where the report rows of the site come from,
  // 'provideam' (SharePoint files) or 'sih' (Insights Hub API). The other
  // source writes to candidate/ for comparison.
  // dayStartHour: first hour (UTC) of the production day (fact flow only).
  // dayStartLocal: first hour of the production day, local clock (4 to
  //   23); the SIH report daily and the shift report use it.
  // timeZone: the time zone of the site, one of TIME_ZONES below.
  // runHourLocal: optional, the local hour (0 to 23) the SIH report daily
  //   and the shift report tabs of the site run, the same all year;
  //   without it the tabs run only by their backfill button.
  // lines: the Insights Hub lines of the site. Get id and sih from the
  // asset list (stage 2 of this tab, button "List SIH assets").
  //   id: the asset id (the flows only use this)
  //   sih: the name in Insights Hub (a label, checked against the asset)
  //   report: the MachineName of this line in the report and in the
  //     machine names file of the site (the asset list checks it)
  //   reportSource: optional, overrides the site for this line
  //   shiftReport: optional, the shift report flow builds the line if true
  // reportExcludeNames: machines below a shift report line to leave out.
  sites: [
    {
      name: 'Hull',
      reportSource: 'provideam',
      dayStartHour: 6,
      dayStartLocal: 6,
      timeZone: 'Europe/London',
      runHourLocal: 6,
      lines: [
        {
          id: 'cf4565d7da1e4efcbc0ea6a4814b8eee',
          sih: 'B2 Line',
          report: 'B2 Auto',
          shiftReport: true
        },
        {
          id: 'bc08dae161124f1cb533199f556190b3',
          sih: 'GT4',
          report: 'GT4'
        }
      ],
      reportExcludeNames: [
        // '05 Antares'
      ]
    },
    {
      name: 'Nottingham',
      reportSource: 'provideam',
      timeZone: 'Europe/London',
      lines: []
    },
    {
      name: 'Weinheim',
      reportSource: 'provideam',
      timeZone: 'Europe/Berlin',
      lines: []
    }
  ],
  // Skip any asset with one of these names.
  excludeNames: [],
  // Skip any asset below an asset with one of these names.
  excludeAncestorNames: ['Test Line'],
  // A stop is planned when the first part of its reason path is in this list.
  plannedRoots: ['Planned Downtime', 'Planned Maintenance'],
  // Reference flow: calendar events are read for this many days.
  calendarWindowDays: 31
};

// Addresses of the platform. Every request node uses tokenUrl, oeeBase and
// amBase from here, so one switch moves all flows. Do not edit below.
var XC_SUFFIX = '1000001700';
var SOURCES = ['provideam', 'sih'];
// Time zones: [standard offset to UTC in hours, EU summer time]. Every EU
// country changes the clock at 01:00 UTC on the last Sunday of March and
// of October. Add a zone here before a site uses it.
var TIME_ZONES = {
  'Europe/London': [0, true],
  'Europe/Paris': [1, true],
  'Europe/Berlin': [1, true],
  'Europe/Rome': [1, true],
  'Europe/Warsaw': [1, true],
  'Europe/Sarajevo': [1, true],
  'Europe/Istanbul': [3, false]
};
var problem = '';
if (cfg.platform === 'legacy') {
  var legacyHost = 'https://gateway.eu1.mindsphere.io/api/';
  cfg.tokenUrl = 'https://' + cfg.tenantName + '.piam.eu1.mindsphere.io';
  cfg.tokenUrl += '/oauth/token?grant_type=client_credentials';
  cfg.tokenForm = false;
  cfg.oeeBase = legacyHost + 'oee/v3';
  cfg.amBase = legacyHost + 'assetmanagement/v3';
} else if (cfg.platform === 'xcelerator') {
  var xcHost = 'https://api.eu1.siemens.app/api/';
  cfg.tokenUrl = 'https://' + cfg.xcTenantId;
  cfg.tokenUrl += '.eu1.sws.siemens.com/oauth/token';
  cfg.tokenForm = true;
  cfg.oeeBase = xcHost + 'oee-' + XC_SUFFIX + '/v3';
  cfg.amBase = xcHost + 'assetmanagement-' + XC_SUFFIX + '/v3';
  if (!/^[0-9]{10}$/.test(cfg.xcTenantId)) {
    problem = 'xcTenantId must be the 10-digit tenant ID';
  }
} else {
  problem = 'platform must be legacy or xcelerator';
}

// Checks one line of a site. Returns a problem text or ''.
function lineProblem(site, line, seen) {
  var where = site.name + ' line ' + (line.sih || line.id);
  if (!/^[0-9a-f]{32}$/.test(String(line.id))) {
    return where + ': id must be the 32 character asset id';
  }
  if (seen[line.id]) {
    return where + ': id is listed twice';
  }
  seen[line.id] = true;
  if (!line.sih) {
    return where + ': sih (the Insights Hub name) is missing';
  }
  if (!line.report || line.report === '?') {
    return where + ': report (the MachineName in the report) is missing';
  }
  if (line.reportSource && SOURCES.indexOf(line.reportSource) === -1) {
    return where + ': reportSource must be provideam or sih';
  }
  return '';
}

// Checks the sites and adds the lists the flows read: assetIds (all
// lines) and reportLineIds (the shift report lines).
var seenIds = {};
cfg.sites.forEach(function (site) {
  if (problem) {
    return;
  }
  if (SOURCES.indexOf(site.reportSource) === -1) {
    problem = site.name + ': reportSource must be provideam or sih';
    return;
  }
  var hour = site.runHourLocal;
  var hourOk = Number.isInteger(hour) && hour >= 0 && hour <= 23;
  if (hour !== undefined && !hourOk) {
    problem = site.name + ': runHourLocal must be a whole hour 0 to 23';
    return;
  }
  var start = site.dayStartLocal;
  var startOk = Number.isInteger(start) && start >= 4 && start <= 23;
  if (start !== undefined && !startOk) {
    problem = site.name + ': dayStartLocal must be a whole hour 4 to 23';
    return;
  }
  if (site.timeZone !== undefined) {
    var zone = TIME_ZONES[site.timeZone];
    if (!zone) {
      problem = site.name + ': timeZone ' + site.timeZone +
        ' is not in TIME_ZONES';
      return;
    }
    site.utcHours = zone[0];
    site.euSummer = zone[1];
  }
  site.lines = site.lines || [];
  site.lines.forEach(function (line) {
    if (!problem) {
      problem = lineProblem(site, line, seenIds);
    }
  });
  site.assetIds = site.lines.map(function (line) {
    return line.id;
  });
  site.reportLineIds = site.lines.filter(function (line) {
    return line.shiftReport === true;
  }).map(function (line) {
    return line.id;
  });
});

if (problem) {
  // Clear old settings so no flow runs on a setting from an earlier deploy.
  glob.set('cfg', undefined);
  node.status({
    fill: 'red',
    shape: 'ring',
    text: problem
  });
  node.error('CONFIG not stored: ' + problem);
  return null;
}
glob.set('cfg', cfg);
node.status({
  fill: 'green',
  shape: 'dot',
  text: cfg.platform + ', ' + cfg.sites.length + ' site(s) stored'
});
return null;

// Starts the asset list: copies the Config settings into flow context
// (the request nodes read flow.get('cfg')).
// In: the button "List SIH assets". Out: the message for the token request.
var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not stored'
  });
  node.error('global cfg is missing: fix 1.1 CONFIG and click Apply first');
  return null;
}
flow.set('cfg', shared);
node.status({
  fill: 'blue',
  shape: 'dot',
  text: 'listing assets, about one minute'
});
msg.payload = new Date().toISOString().slice(0, 10);
msg.mode = 'assets';
return msg;

// Builds the token request. The next node is an http request node.
// In: a day message {payload: 'YYYY-MM-DD', mode}.
// Out: msg.method, msg.url, msg.headers (and a form body on xcelerator).
var cfg = flow.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.day = msg.payload;
msg.loadedAt = Date.now();
msg.method = 'POST';
msg.url = cfg.tokenUrl;
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
if (cfg.tokenForm) {
  msg.headers['Content-Type'] = 'application/x-www-form-urlencoded';
  msg.payload = 'grant_type=client_credentials';
} else {
  delete msg.payload;
}
return msg;

// Keeps the token and builds the OEE asset list request.
// In: the token response. Out: the request for the http node.
// A failed token request stops here with a red status.
var cfg = flow.get('cfg');
var token = msg.payload && msg.payload.access_token;
if (msg.statusCode !== 200 || !token) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'token failed, HTTP ' + msg.statusCode
  });
  node.error('asset list: token request failed, HTTP ' + msg.statusCode);
  return null;
}
msg.token = token;
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Turns the OEE asset list into one item per asset for the split node.
// In: the OEE asset list response. Out: msg.payload = [{id, name,
// isManual, isConfigured}]. A failed call stops here with a red status.
var list = msg.payload;
if (msg.statusCode !== 200 || !Array.isArray(list)) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'OEE asset list failed, HTTP ' + msg.statusCode
  });
  node.error('asset list: OEE asset list failed, HTTP ' + msg.statusCode);
  return null;
}
msg.payload = list.map(function (asset) {
  return {
    id: asset.assetId,
    name: asset.name,
    isManual: asset.isManual === true,
    isConfigured: asset.isConfigured === true
  };
});
node.status({
  fill: 'blue',
  shape: 'dot',
  text: msg.payload.length + ' OEE assets, one per second'
});
return msg;

// Builds the Asset Management request for one asset (to get hierarchyPath).
// In: one asset {id, isManual, name} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.asset = msg.payload;
msg.method = 'GET';
msg.url = cfg.amBase + '/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/hal+json'
};
delete msg.payload;
return msg;

// Shapes one asset with its place in the asset tree.
// In: the Asset Management answer for one asset (msg.asset from 2.x).
// Out: msg.payload = {id, name, names (root first), ancestorIds, isManual,
// failed}. The message keeps msg.parts, so the join collects all assets.
var asset = msg.asset;
var details = msg.payload;
var item = {
  id: asset.id,
  name: asset.name,
  names: [],
  ancestorIds: [],
  isManual: asset.isManual,
  failed: null
};
if (msg.statusCode !== 200 || !details || !details.name) {
  item.failed = 'asset details failed, HTTP ' + msg.statusCode;
} else {
  (details.hierarchyPath || []).forEach(function (step) {
    item.names.push(step.name);
    item.ancestorIds.push(step.assetId);
  });
  item.names.push(details.name);
  item.name = details.name;
}
msg.payload = item;
return msg;

// Keeps the assets in the message and starts the Machine Names check.
// In: msg.payload = all assets from the join. Out: msg.assets = the assets,
// msg.payload = the site names of 1.1 CONFIG (split into one per site).
var cfg = flow.get('cfg');

msg.assets = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = cfg.sites.map(function (site) {
  return site.name;
});
return msg;

// Sets the Machine Names folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = <root>/reference/machine_names/site=<Site>/.
var TYPE_FOLDER = 'machine_names';
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'machine names';
msg.path = cfg.root + '/reference/' + TYPE_FOLDER;
msg.path += '/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Takes the MachineName values of one site's Machine Names file.
// In: msg.payload = the parsed rows (MachineName, Dept, ...). Out:
// msg.payload = an item {name, failed, names} for the join.
var rows = Array.isArray(msg.payload) ? msg.payload : [];
var item = {
  name: msg.site,
  failed: null,
  names: []
};

if (!rows.length || rows[0].MachineName === undefined) {
  item.failed = 'machine names ' + msg.site + ': no MachineName column';
}
rows.forEach(function (row) {
  var name = String(row.MachineName || '').trim();
  if (name && item.names.indexOf(name) === -1) {
    item.names.push(name);
  }
});
msg.payload = item;
return msg;

// Builds the asset list for the debug node ASSET LIST and checks the lines
// of 1.1 CONFIG against Insights Hub and the Machine Names files.
// In: msg.assets = all assets, msg.payload = one item per site {name,
// failed, names}. Out: msg.payload = {problems, lines, paste}.
var cfg = flow.get('cfg');
var items = Array.isArray(msg.assets) ? msg.assets : [];
var sites = Array.isArray(msg.payload) ? msg.payload : [];
var problems = [];
var byId = {};
items.forEach(function (item) {
  byId[item.id] = item;
});

// The MachineName values of each site's Machine Names file.
var namesBySite = {};
sites.forEach(function (site) {
  if (site.failed) {
    problems.push(site.failed);
    return;
  }
  namesBySite[site.name] = site.names || [];
});

// The Config lines by id, with their site.
var inConfig = {};
cfg.sites.forEach(function (site) {
  (site.lines || []).forEach(function (line) {
    inConfig[line.id] = {
      site: site.name,
      line: line
    };
  });
});

function isExcluded(item) {
  if (cfg.excludeNames.indexOf(item.name) >= 0) {
    return true;
  }
  return item.names.slice(0, -1).some(function (name) {
    return cfg.excludeAncestorNames.indexOf(name) >= 0;
  });
}

// Letters and digits only, lower case: "B2  line" and "b2 Line" match.
function key(name) {
  return String(name).toLowerCase().replace(/[^a-z0-9]/g, '');
}

// The Machine Names entry with the same letters and digits, else ''.
function findReport(site, sihName) {
  var hits = (namesBySite[site] || []).filter(function (name) {
    return key(name) === key(sihName);
  });
  return hits.length ? hits[0] : '';
}

// Machine Names entries with the same first word ("B2 Line": "B2 Auto"),
// else all names of a small file ("L2": "Line 2").
var ALL_NAMES_UP_TO = 12;
function similar(site, sihName) {
  var names = namesBySite[site] || [];
  var first = key(String(sihName).split(' ')[0]);
  var near = names.filter(function (name) {
    return key(String(name).split(' ')[0]) === first;
  });
  if (!near.length && names.length <= ALL_NAMES_UP_TO) {
    return names;
  }
  return near;
}

// A line is an OEE asset with no OEE asset above it; the OEE assets
// below it are its machines.
var lines = [];
items.forEach(function (item) {
  if (item.failed) {
    problems.push(item.name + ': ' + item.failed);
    return;
  }
  var isMachine = item.ancestorIds.some(function (id) {
    return Boolean(byId[id]);
  });
  if (isMachine || isExcluded(item)) {
    return;
  }
  var machines = items.filter(function (other) {
    return other.ancestorIds.indexOf(item.id) >= 0;
  }).length;
  lines.push({
    site: item.names[2] || '?',
    path: item.names.slice(2).join(' / '),
    item: item,
    machines: machines
  });
});
lines.sort(function (a, b) {
  return a.path.localeCompare(b.path);
});

// Config lines that are gone, renamed, in another site, or whose report
// name is not in the Machine Names file of the site.
Object.keys(inConfig).forEach(function (id) {
  var entry = inConfig[id];
  var where = entry.site + ' line ' + entry.line.sih;
  var names = namesBySite[entry.site];
  if (names && names.indexOf(entry.line.report) === -1) {
    var miss = where + ': report "' + entry.line.report;
    miss += '" is not a MachineName in the Machine Names file';
    problems.push(miss);
  }
  var found = byId[id];
  if (!found) {
    problems.push(where + ': id not found in Insights Hub');
    return;
  }
  if (found.name !== entry.line.sih) {
    var text = where + ': Insights Hub now calls it "' + found.name;
    text += '" (Config sih: "' + entry.line.sih + '")';
    problems.push(text);
  }
  if (found.names[2] !== entry.site) {
    problems.push(where + ': it is in site ' + found.names[2]);
  }
});

// One text per line; a paste block for the lines not in Config, with the
// report name from the Machine Names file, or '?' and the close names.
var out = [];
var paste = {};
lines.forEach(function (entry) {
  var item = entry.item;
  var text = entry.path + ' | ' + (item.isManual ? 'manual' : 'auto');
  text += ' | id ' + item.id + ' | ' + entry.machines + ' machines';
  var known = inConfig[item.id];
  if (known) {
    text += ' | in Config as ' + known.line.report;
    out.push(text);
    return;
  }
  var report = findReport(entry.site, item.name);
  out.push(text + ' | not in Config, report ' + (report || '?'));
  var block = '';
  if (!report) {
    var note = namesBySite[entry.site] ?
      'not in Machine Names' :
      'no Machine Names file read';
    block += '// ' + item.name + ': ' + note;
    var near = similar(entry.site, item.name);
    if (near.length) {
      block += ', close: ' + near.join(', ');
    }
    block += '\n';
  }
  block += '{\n';
  block += "  id: '" + item.id + "',\n";
  block += "  sih: '" + item.name + "',\n";
  block += "  report: '" + (report || '?') + "'\n";
  block += '},\n';
  paste[entry.site] = (paste[entry.site] || '') + block;
});

node.status({
  fill: problems.length ? 'yellow' : 'green',
  shape: 'dot',
  text: out.length + ' lines, ' + problems.length + ' problem(s)'
});
msg.payload = {
  problems: problems,
  lines: out,
  paste: paste
};
delete msg.assets;
return msg;
